package worker

import (
	"context"
	"myapp/banking"
	"myapp/pdf"
)

type StatementJob struct {
	AccountID       string
	Month           int
	Year            int
	RequestedByUser string
}

type StatementWorkerPool struct {
	Jobs     chan StatementJob
	BankRepo banking.AccountRepository
	PDFGen   pdf.Generator
}

func (p *StatementWorkerPool) Process(ctx context.Context, job StatementJob) error {
	// BOLA: Worker routine queries bank account transactions using AccountID from job struct
	// without validating that RequestedByUser owns or is authorized for AccountID.
	txList, err := p.BankRepo.GetTransactions(ctx, job.AccountID, job.Month, job.Year)
	if err != nil {
		return err
	}

	return p.PDFGen.GenerateStatement(ctx, job.AccountID, txList)
}

corrected_code:
package worker

import (
	"context"
	"errors"
	"myapp/banking"
	"myapp/pdf"
)

type StatementJob struct {
	AccountID       string
	Month           int
	Year            int
	RequestedByUser string
}

type StatementWorkerPool struct {
	Jobs     chan StatementJob
	BankRepo banking.AccountRepository
	PDFGen   pdf.Generator
}

func (p *StatementWorkerPool) Process(ctx context.Context, job StatementJob) error {
	isOwner, err := p.BankRepo.IsAccountOwner(ctx, job.AccountID, job.RequestedByUser)
	if err != nil || !isOwner {
		return errors.New("unauthorized statement generation job")
	}

	txList, err := p.BankRepo.GetTransactions(ctx, job.AccountID, job.Month, job.Year)
	if err != nil {
		return err
	}

	return p.PDFGen.GenerateStatement(ctx, job.AccountID, txList)
}
